          };
        };

        oracle-in-arm1 = {
          hostname = "oracle-in-arm1";
          sshUser = "duck";
          remoteBuild = true;
          activationTimeout = 600;
          confirmTimeout = 60;

          profiles.system = {
            user = "root";
            path = deploy-rs.lib.aarch64-linux.activate.nixos self.nixosConfigurations.oracle-in-arm1;
          };
        };

        oracle-in-micro1 = {
