{
  imports = [ ./k3s-agent.nix ];

  services.k3s.extraFlags = [
    "--kubelet-arg=max-pods=10"
  ];

  zramSwap = {
    enable = true;
    algorithm = "zstd";
    memoryPercent = 50;

