 # profiles/base.nix — applied to every OCI host
 #
 # Provides the absolute baseline: nix daemon settings, garbage collection,
 # minimal system footprint, and the shared user account.
 { ... }:
 {
   # Nix settings
   nix.settings = {
     trusted-users = [
       "root"
       "duck"
     ];
     substituters = [
       "https://cache.nixos.org"
       "https://nix-community.cachix.org"
     ];
     trusted-public-keys = [
       "cache.nixos.org-1:REDACTED"
       "nix-community.cachix.org-1:b9F6KGrNS7LDfJs+c9UF4/tEaS7KE0mTChZdG4h6IVk="
     ];
   };

   nix.gc = {
     automatic = true;
     dates = "weekly";
     options = "--delete-older-than 7d";
     randomizedDelaySec = "45min";
   };

   nix.optimise = {
     automatic = true;
     dates = [ "weekly" ];
     randomizedDelaySec = "45min";
   };

   # Minimal system — no docs, no default packages
   documentation.enable = false;
   programs.command-not-found.enable = false;
   environment.defaultPackages = [ ];
   environment.systemPackages = [ ];

   # Shared user account
   users.mutableUsers = false;

   users.users.root = {
     hashedPassword = "!";
     openssh.authorizedKeys.keys = [ ];
   };

   users.users.duck = {
     isNormalUser = true;

     extraGroups = [
       "wheel"
       "networkmanager"
     ];

     hashedPassword = "!";

     openssh.authorizedKeys.keys = [
       "ssh-ed25519 REDACTED jesbin@Duck.local"
       "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIEDGmT5meeiDIK9c/W8imy++S7hb9TLBcHcPsWcml4D2 duck@Ducks-MacBook-Air.local"
       "ssh-ed25519 REDACTED jesbin@Jesbins-MacBook-Pro.local"
     ];
   };

   security.sudo.wheelNeedsPassword = false;
-
-  # nixpkgs-unstable pam_unix now rejects accounts with locked passwords
-  # ("!"), which breaks SSH key auth (succeeds key check, then PAM kills
-  # the connection) and sudo.  Bypass the account check with pam_permit.
-  security.pam.services.sshd.text = ''
-    auth required pam_unix.so no_warn try_first_pass nullok
-    account required pam_permit.so
-    password required pam_unix.so no_warn try_first_pass nullok sha512 shadow
-    session required pam_unix.so no_warn try_first_pass nullok
-  '';
-
-  security.pam.services.sudo.text = ''
-    auth sufficient pam_permit.so
-    account sufficient pam_permit.so
-    password sufficient pam_permit.so
-    session sufficient pam_permit.so
-  '';
 }

