    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://raw.githubusercontent.com/bjw-s-labs/helm-charts/common-5.0.1/charts/library/common/schemas/persistence.json",
  "$defs": {
    "item": {
      "properties": {
        "enabled": {
          "description": "Set to false to disable the persistence item.",
          "type": "boolean",
          "default": true
        },
        "globalMounts": {
          "$ref": "#/$defs/globalMounts",
          "description": "Configure mounts to all controllers and containers.\nBy default the persistence item will be mounted to /<name_of_the_persistence_item>.\nEach entry supports: path, readOnly, subPath, subPathExpr, and mountPropagation."
        },
        "advancedMounts": {
          "$ref": "#/$defs/advancedMounts",
          "description": "Explicitly configure mounts for specific controllers and containers.\nStructure: advancedMounts.<controller_name>.<container_name>[].path\nUse this instead of globalMounts when different controllers need different mount configurations."
        }
      },
      "unevaluatedProperties": false,
      "oneOf": [
        {
          "$ref": "#/$defs/item.type.persistentVolumeClaim"
        },
        {
          "$ref": "#/$defs/item.type.persistentVolumeClaimExisting"
        },
        {
          "$ref": "#/$defs/item.type.configMap"
        },
        {
          "$ref": "#/$defs/item.type.secret"
        },
        {
          "$ref": "#/$defs/item.type.nfs"
        },
        {
          "$ref": "#/$defs/item.type.emptyDir"
        },
        {
          "$ref": "#/$defs/item.type.ephemeral"
        },
        {
          "$ref": "#/$defs/item.type.hostPath"
        },
        {
          "$ref": "#/$defs/item.type.image"
        },
        {
          "$ref": "#/$defs/item.type.custom"
        }
      ]
    },
    "item.type.persistentVolumeClaim": {
      "type": "object",
      "description": "Dynamically provision a PersistentVolumeClaim. This is the default persistence type and will be used when no type is specified.",
      "examples": [
        "persistence:\n  config:\n    type: persistentVolumeClaim\n    accessMode: ReadWriteOnce\n    size: 1Gi",
        "persistence:\n  config:\n    type: persistentVolumeClaim\n    accessMode: ReadWriteOnce\n    size: 10Gi\n    storageClass: fast-ssd\n    retain: true\n    globalMounts:\n      - path: /config"
      ],
      "allOf": [
        {
          "$ref": "definitions.json#/$defs/resourceIdentifier"
        }
      ],
      "required": [
        "accessMode",
        "size"
      ],
      "properties": {
        "type": {
          "const": "persistentVolumeClaim"
        },
        "accessMode": {
          "type": "string",
          "description": "AccessMode for the persistent volume. Make sure to select an access mode that is supported by your storage provider!\nSee https://kubernetes.io/docs/concepts/storage/persistent-volumes/#access-modes"
        },
        "annotations": {
          "$ref": "definitions.json#/$defs/annotations"
        },
        "dataSource": {
          "$ref": "#/$defs/dataSourceReference",
          "description": "The optional data source for the persistentVolumeClaim.\nSee https://kubernetes.io/docs/concepts/storage/persistent-volumes/#volume-populators-and-data-sources"
        },
        "dataSourceRef": {
          "$ref": "#/$defs/dataSourceReference",
          "description": "The optional volume populator for the persistentVolumeClaim.\nSee https://kubernetes.io/docs/concepts/storage/persistent-volumes/#volume-populators-and-data-sources"
        },
        "labels": {
          "$ref": "definitions.json#/$defs/labels"
        },
        "retain": {
          "type": "boolean",
          "description": "Set to true to retain the PVC upon helm uninstall."
        },
        "size": {
          "type": "string",
          "description": "The amount of storage that is requested for the persistent volume."
        },
        "storageClass": {
          "type": "string",
          "description": "Storage Class for the config volume.\nIf set to '-', dynamic provisioning is disabled.\nIf set to something else, the given storageClass is used.\nIf undefined (the default) or set to null, no storageClassName spec is set, choosing the default provisioner."
        },
        "volumeName": {
          "type": "string"
        }
      }
    },
    "item.type.persistentVolumeClaimExisting": {
      "type": "object",
      "description": "Attach an existing PersistentVolumeClaim instead of creating a new one.",
      "examples": [
        "persistence:\n  config:\n    type: persistentVolumeClaim\n    existingClaim: my-app-data"
      ],
      "required": [
        "existingClaim"
      ],
      "properties": {
        "type": {
          "const": "persistentVolumeClaim"
        },
        "existingClaim": {
          "type": "string",
          "description": "The name of an existing PersistentVolumeClaim to use. Helm templates are supported.\nThis will not create a new PVC, but use the existing one instead."
        }
      }
    },
    "item.type.configMap": {
      "type": "object",
      "description": "Mount a ConfigMap as a volume. Use 'name' for external ConfigMaps, or 'identifier' to reference one managed by this chart.",
      "examples": [
        "persistence:\n  config:\n    type: configMap\n    name: my-configmap",
        "persistence:\n  config:\n    type: configMap\n    identifier: my-chart-configmap\n    globalMounts:\n      - path: /etc/app/config\n        readOnly: true",
        "persistence:\n  config:\n    type: configMap\n    name: my-configmap\n    items:\n      - key: settings.yaml\n        path: settings.yaml"
      ],
      "required": [
        "type"
      ],
      "$comment": "oneOf enforces that at least one of name/identifier is present. dependentSchemas enforces mutual exclusion with a targeted error when both are set. Both are needed — do not simplify to oneOf alone.",
      "oneOf": [
        {
          "required": [
            "name"
          ]
        },
        {
          "required": [
            "identifier"
          ]
        }
      ],
      "dependentSchemas": {
        "name": {
          "not": {
            "required": [
              "identifier"
            ]
          }
        },
        "identifier": {
          "not": {
            "required": [
              "name"
            ]
          }
        }
      },
      "properties": {
        "type": {
          "const": "configMap"
        },
        "name": {
          "type": "string"
        },
        "identifier": {
          "type": "string"
        },
        "defaultMode": {
          "type": "integer",
          "format": "int32"
        },
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "key": {
                "type": "string"
              },
              "mode": {
                "format": "int32",
                "type": "integer"
              },
              "path": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "item.type.secret": {
      "type": "object",
      "description": "Mount a Secret as a volume. Use 'name' for external Secrets, or 'identifier' to reference one managed by this chart.",
      "examples": [
        "persistence:\n  credentials:\n    type: secret\n    name: my-secret",
        "persistence:\n  tls:\n    type: secret\n    name: app-tls-cert\n    globalMounts:\n      - path: /etc/ssl/certs\n        readOnly: true"
      ],
      "required": [
        "type"
      ],
      "$comment": "oneOf enforces that at least one of name/identifier is present. dependentSchemas enforces mutual exclusion with a targeted error when both are set. Both are needed — do not simplify to oneOf alone.",
      "oneOf": [
        {
          "required": [
            "name"
          ]
        },
        {
          "required": [
            "identifier"
          ]
        }
      ],
      "dependentSchemas": {
        "name": {
          "not": {
            "required": [
              "identifier"
            ]
          }
        },
        "identifier": {
          "not": {
            "required": [
              "name"
            ]
          }
        }
      },
      "properties": {
        "type": {
          "const": "secret"
        },
        "name": {
          "type": "string"
        },
        "identifier": {
          "type": "string"
        },
        "defaultMode": {
          "type": "integer",
          "format": "int32"
        },
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "key": {
                "type": "string"
              },
              "mode": {
                "format": "int32",
                "type": "integer"
              },
              "path": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "item.type.nfs": {
      "type": "object",
      "description": "Mount an NFS share as a volume.",
      "examples": [
        "persistence:\n  media:\n    type: nfs\n    server: 192.168.1.100\n    path: /mnt/share/media",
        "persistence:\n  backups:\n    type: nfs\n    server: nas.example.lan\n    path: /volume/Backups/k8s/app\n    globalMounts:\n      - path: /backups"
      ],
      "required": [
        "type",
        "server",
        "path"
      ],
      "properties": {
        "type": {
          "const": "nfs"
        },
        "path": {
          "type": "string",
          "description": "The NFS export path on the server."
        },
        "server": {
          "type": "string",
          "description": "The NFS server hostname or IP address."
        }
      }
    },
    "item.type.emptyDir": {
      "type": "object",
      "description": "Use an emptyDir volume for scratch space or sharing data between containers in the same pod. Data is lost when the pod is removed.",
      "examples": [
        "persistence:\n  tmp:\n    type: emptyDir",
        "persistence:\n  cache:\n    type: emptyDir\n    medium: Memory\n    sizeLimit: 256Mi"
      ],
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "const": "emptyDir"
        },
        "medium": {
          "type": "string",
          "description": "Storage medium. Set to 'Memory' for tmpfs (RAM-backed). Leave empty for node disk."
        },
        "sizeLimit": {
          "type": "string",
          "description": "Maximum size of the volume (e.g. '1Gi'). Only enforced for tmpfs."
        }
      }
    },
    "item.type.ephemeral": {
      "type": "object",
      "description": "Use a generic ephemeral volume for scratch space or sharing data between containers. The volume is created and deleted with the pod.",
      "examples": [
        "persistence:\n  cache:\n    type: ephemeral",
        "persistence:\n  cache:\n    type: ephemeral\n    accessMode: ReadWriteOnce\n    storageClass: fast-ssd\n    size: 10Gi"
      ],
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "const": "ephemeral"
        },
        "accessMode": {
          "type": "string",
          "description": "AccessMode for the ephemeral volume. Make sure to select an access mode that is supported by your storage provider!\nSee https://kubernetes.io/docs/concepts/storage/persistent-volumes/#access-modes"
        },
        "storageClass": {
          "type": "string",
          "description": "Storage Class for the ephemeral volume.\nIf set to '-', dynamic provisioning is disabled.\nIf set to something else, the given storageClass is used.\nIf undefined (the default) or set to null, no storageClassName spec is set, choosing the default provisioner."
        },
        "size": {
          "type": "string",
          "description": "The amount of storage that is requested for the ephemeral volume."
        }
      }
    },
    "item.type.hostPath": {
      "type": "object",
      "description": "Mount a path from the host node into the pod. Use with caution as it ties the pod to a specific node.",
      "examples": [
        "persistence:\n  dev-tun:\n    type: hostPath\n    hostPath: /dev/net/tun\n    hostPathType: CharDevice",
        "persistence:\n  data:\n    type: hostPath\n    hostPath: /mnt/local-data\n    hostPathType: DirectoryOrCreate"
      ],
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "const": "hostPath"
        },
        "hostPath": {
          "type": "string",
          "description": "Path on the host node to mount."
        },
        "hostPathType": {
          "type": "string",
          "description": "Type of the host path. Values: DirectoryOrCreate, Directory, FileOrCreate, File, Socket, CharDevice, BlockDevice."
        }
      }
    },
    "item.type.image": {
      "type": "object",
      "description": "Mount OCI image or artifact contents as a read-only volume. Requires Kubernetes 1.31+ with the ImageVolume feature gate.",
      "examples": [
        "persistence:\n  static-assets:\n    type: image\n    image: registry.example.com/assets:v1.0",
        "persistence:\n  tools:\n    type: image\n    image:\n      repository: registry.example.com/tools\n      tag: latest\n    pullPolicy: Always"
      ],
      "required": [
        "type",
        "image"
      ],
      "properties": {
        "type": {
          "const": "image"
        },
        "image": {
          "description": "OCI artifact reference to be used.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "$ref": "definitions.json#/$defs/imageSpecification"
            }
          ]
        },
        "pullPolicy": {
          "description": "The image pull policy for the image persistence item.",
          "type": "string",
          "enum": [
            "Always",
            "Never",
            "IfNotPresent"
          ]
        }
      }
    },
    "item.type.custom": {
      "type": "object",
      "description": "Specify a custom volume type not covered by the built-in types. The volumeSpec is passed through directly to the pod spec.",
      "examples": [
        "persistence:\n  ceph:\n    type: custom\n    volumeSpec:\n      cephfs:\n        monitors:\n          - 10.0.0.1:6789\n        user: admin\n        secretRef:\n          name: ceph-secret",
        "persistence:\n  projected:\n    type: custom\n    volumeSpec:\n      projected:\n        sources:\n          - secret:\n              name: my-secret\n          - configMap:\n              name: my-config"
      ],
      "required": [
        "type",
        "volumeSpec"
      ],
      "properties": {
        "type": {
          "const": "custom"
        },
        "volumeSpec": {
          "type": "object",
          "description": "Raw Kubernetes volume specification. Passed through directly to the pod spec volumes list."
        }
      }
    },
    "dataSourceReference": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind",
        "name"
      ],
      "properties": {
        "apiGroup": {
          "type": "string"
        },
        "kind": {
          "type": "string"
        },
        "name": {
          "type": "string"
        }
      }
    },
    "globalMounts": {
      "description": "Mount the volume to all controllers and containers. Each entry specifies a mount point.",
      "type": "array",
      "examples": [
        "globalMounts:\n  - path: /config",
        "globalMounts:\n  - path: /data\n    readOnly: true\n  - path: /data/subdir\n    subPath: subdir"
      ],
      "items": {
        "$ref": "#/$defs/mountPath"
      }
    },
    "advancedMounts": {
      "description": "Mount the volume to specific controllers and containers. Use when different containers need different mount configurations.",
      "examples": [
        "advancedMounts:\n  main:\n    main:\n      - path: /config\n    sidecar:\n      - path: /shared\n        readOnly: true"
      ],
      "additionalProperties": {
        "type": "object",
        "additionalProperties": {
          "$ref": "#/$defs/mountPathCollection"
        }
      }
    },
    "mountPathCollection": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/mountPath"
      }
    },
    "mountPath": {
      "additionalProperties": false,
      "properties": {
        "path": {
          "type": "string",
          "description": "The path where the volume should be mounted in the container. Helm templates are supported.\nIf not specified, the mount path will be set to /<identifier_of_the_peristence_item>."
        },
        "readOnly": {
          "type": "boolean"
        },
        "subPath": {
          "type": "string",
          "description": "The subPath within the volume to mount. Helm templates are supported.\nIf not specified, the entire volume will be mounted."
        },
        "subPathExpr": {
          "type": "string"
        },
        "mountPropagation": {
          "type": "string"
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://raw.githubusercontent.com/bjw-s-labs/helm-charts/common-5.0.1/charts/library/common/schemas/pod.json",
  "$defs": {
    "options": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "affinity": {
          "$ref": "k8s-api.json#/$defs/core.v1.Affinity",
          "description": "Set affinity constraint rules. Helm templates can be used.\nSee https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/#affinity-and-anti-affinity"
        },
        "annotations": {
          "$ref": "definitions.json#/$defs/annotations"
        },
        "automountServiceAccountToken": {
          "type": "boolean",
          "default": false,
          "description": "Set to true to automatically mount the service account token."
        },
        "dnsConfig": {
          "$ref": "k8s-api.json#/$defs/core.v1.PodDNSConfig",
          "description": "Specifies the DNS parameters of a pod. Parameters specified here will be merged to the generated DNS configuration based on DNSPolicy. Configuring the `ndots` option may resolve nslookup issues on some Kubernetes setups."
        },
        "dnsPolicy": {
          "type": "string",
          "description": "Configure the Pod DNS policy. Defaults to 'ClusterFirst' if hostNetwork is false and 'ClusterFirstWithHostNet' if hostNetwork is true."
        },
        "enableServiceLinks": {
          "type": "boolean",
          "default": false,
          "description": "Enable/disable the generation of environment variables for services.\nSee https://kubernetes.io/docs/concepts/services-networking/connect-applications-service/#accessing-the-service"
        },
        "hostAliases": {
          "type": "array",
          "items": {
            "$ref": "k8s-api.json#/$defs/core.v1.HostAlias"
          },
          "description": "Use hostAliases to add custom entries to /etc/hosts - mapping IP addresses to hostnames.\nSee https://kubernetes.io/docs/concepts/services-networking/add-entries-to-pod-etc-hosts-with-host-aliases/"
        },
        "hostIPC": {
          "type": "boolean",
          "default": false,
          "description": "Set to true to use the host's ipc namespace."
        },
        "hostNetwork": {
          "type": "boolean",
          "default": false,
          "description": "Set to false to disable host networking on the Pod. When using hostNetwork, make sure you set dnsPolicy to 'ClusterFirstWithHostNet'"
        },
        "hostPID": {
          "type": "boolean",
          "default": false,
          "description": "Set to true to use the host's pid namespace."
        },
        "hostUsers": {
          "type": [
            "boolean",
            "null"
          ],
          "description": "Set to false to create a new userns for the Pod. (Requires Kubernetes 1.29 or newer)"
        },
        "hostname": {
          "type": "string",
          "description": "Set the Pod's hostname."
        },
        "imagePullSecrets": {
          "type": "array",
          "items": {
            "$ref": "k8s-api.json#/$defs/core.v1.LocalObjectReference"
          },
          "description": "Set image pull secrets."
        },
        "labels": {
          "$ref": "definitions.json#/$defs/labels"
        },
        "nodeSelector": {
          "type": "object",
          "additionalProperties": {
            "type": [
              "string"
            ]
          },
          "description": "Node selection constraint.\nSee https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/#nodeselector"
        },
        "priorityClassName": {
          "type": "string",
          "description": "Custom priority class for different treatment by the scheduler."
        },
        "resources": {
          "description": "Set the resource requests / limits for the Pod. (Requires Kubernetes 1.32 or newer)",
          "$ref": "k8s-api.json#/$defs/core.v1.ResourceRequirements"
        },
        "resourceClaims": {
          "description": "ResourceClaims defines which ResourceClaims must be allocated and reserved before the Pod is allowed to start. The resources will be made available to those containers which consume them by name. (Requires Kubernetes 1.32 or newer)",
          "type": "array",
          "items": {
            "$ref": "k8s-api.json#/$defs/core.v1.PodResourceClaim"
          }
        },
        "resizePolicy": {
          "description": "Pod-level resize policy for controlling container restart on resource resize. (Requires Kubernetes 1.36 or newer with InPlacePodLevelResourcesVerticalScaling enabled)",
          "type": "array",
          "items": {
            "$ref": "k8s-api.json#/$defs/core.v1.ContainerResizePolicy"
          }
        },
        "restartPolicy": {
          "type": "string",
          "description": "Set container restart policy. Defaults to 'Always'. When controller.type is 'cronjob' it defaults to 'Never'."
        },
        "runtimeClassName": {
          "type": "string",
          "description": "Set a runtimeClassName other than the default one (ie: `nvidia`)."
        },
        "schedulerName": {
          "type": "string",
          "description": "Set a custom scheduler name."
        },
        "schedulingGates": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string",
                "description": "Name of the scheduling gate. Each gate is a string literal that represents a criteria that Pod should be satisfied before considered schedulable."
              }
            },
            "required": [
              "name"
            ],
            "additionalProperties": false
          },
          "description": "SchedulingGates is an opaque list of values that if specified will block scheduling the pod. If schedulingGates is not empty, the pod will stay in the SchedulingGated state and the scheduler will not attempt to schedule the pod.\nSee https://kubernetes.io/docs/concepts/scheduling-eviction/pod-scheduling-readiness/"
        },
        "securityContext": {
          "$ref": "k8s-api.json#/$defs/core.v1.PodSecurityContext",
          "description": "Configure the Security Context for the Pod."
        },
        "shareProcessNamespace": {
          "type": [
            "boolean",
            "null"
          ],
          "default": false,
          "description": "Allows sharing process namespace between containers in a Pod.\nSee https://kubernetes.io/docs/tasks/configure-pod-container/share-process-namespace/"
        },
        "terminationGracePeriodSeconds": {
          "type": [
            "integer",
            "null"
          ],
          "description": "Duration in seconds the pod needs to terminate gracefully.\nSee https://kubernetes.io/docs/reference/kubernetes-api/workload-resources/pod-v1/#lifecycle"
        },
        "tolerations": {
          "type": "array",
          "items": {
            "$ref": "k8s-api.json#/$defs/core.v1.Toleration"
          },
          "description": "Specify taint tolerations.\nSee https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/"
        },
        "topologySpreadConstraints": {
          "type": "array",
          "items": {
            "$ref": "k8s-api.json#/$defs/core.v1.TopologySpreadConstraint"
          },
          "description": "Defines topologySpreadConstraint rules.\nSee https://kubernetes.io/docs/concepts/workloads/pods/pod-topology-spread-constraints/"
        }
      }
    }
  }
}

