Index: anywhere/hosts/pro-darwin/darwin-configuration.nix
===================================================================
--- anywhere/hosts/pro-darwin/darwin-configuration.nix	
+++ anywhere/hosts/pro-darwin/darwin-configuration.nix	
@@ -1,118 +1,120 @@
 # hosts/pro-darwin/darwin-configuration.nix — macOS system configuration
 #
 # Managed by nix-darwin + Determinate Nix. Rebuild with:
 #   darwin-rebuild switch --flake .#pro-darwin
 { config, lib, pkgs, ... }:

 {
   # Determinate Nix manages the Nix installation, daemon, and settings.
   # Custom Nix config goes in /etc/nix/nix.custom.conf, not here.
   nix.enable = false;

   nixpkgs.config.allowUnfreePredicate = pkg: builtins.elem (lib.getName pkg) [
     "1password"
+    "cursor"
     "slack"
     "spotify"
   ];

   documentation.enable = false;
   documentation.doc.enable = false;
   documentation.man.enable = false;

   system.stateVersion = 7;
   system.primaryUser = "jesbin";

   system.defaults = {
     dock = {
       autohide = true;
       mru-spaces = false;
       minimize-to-application = true;
       show-recents = false;
     };
     finder = {
       AppleShowAllExtensions = true;
       FXPreferredViewStyle = "Nlsv";
       ShowPathbar = true;
     };
     NSGlobalDomain = {
       AppleShowAllExtensions = true;
       InitialKeyRepeat = 15;
       KeyRepeat = 2;
       NSAutomaticSpellingCorrectionEnabled = false;
     };
   };

   homebrew = {
     enable = true;
     onActivation.cleanup = "none";
     onActivation.autoUpdate = false;
     masApps = {
       "WireGuard" = 1451685025;
       "Bitwarden" = 1352778147;
     };
     casks = [
       "arc"
+      "chatgpt"
       "cloudflare-warp"
       "docker"
       "handy"
       "loom"
       "maccy"
       "tailscale-app"
       "visual-studio-code"
       "warp"
       "whatsapp"
     ];
   };

   security.pam.services.sudo_local.touchIdAuth = true;

   environment.systemPackages = [ pkgs.defaultbrowser pkgs._1password-gui ];

   # nix-darwin ≥ 26.05 only runs three shell-code slots on activation:
   # `preActivation.text`, `extraActivation.text`, `postActivation.text`.
   # Custom names like `system.activationScripts.installFoo` are silently
   # NOT executed — they only produce dead file derivations. All custom
   # activation must go here. See:
   #   https://github.com/nix-darwin/nix-darwin/blob/main/modules/system/activation-scripts.nix
   system.activationScripts.postActivation.text = ''
     # --- Default browser (Arc) --------------------------------------------
     defaultbrowser company.thebrowser.Browser || true

     # --- Maccy: 100 ms clipboard poll (default 500 ms) --------------------
     defaults write org.p0deje.Maccy clipboardCheckInterval -float 0.1

     # --- Blocked gcloud components ----------------------------------------
     # `google-cloud-sdk` from nixpkgs / Homebrew rejects
     # `gcloud components install` ("managed by an external package manager").
     # Workaround: pull Google's official component tarball and drop the
     # binary into /usr/local/bin. Bump URLs from:
     #   https://dl.google.com/dl/cloudsdk/channels/rapid/components-2.json
     # (look for `<component>-darwin-arm` -> `data.source`).
     install_gcloud_component() {
       local name="$1" url="$2" bin="/usr/local/bin/$1"
       if [ -x "$bin" ]; then
         echo "$name already installed"
         return 0
       fi
       echo "Installing $name..."
       local tmp
       tmp=$(mktemp -d)
       # trap in a subshell so it doesn't stomp postActivation's own traps
       (
         trap 'rm -rf "$tmp"' EXIT
         curl -fsSL "$url" -o "$tmp/pkg.tar.gz"
         tar -xzf "$tmp/pkg.tar.gz" -C "$tmp"
         install -m 755 "$tmp/bin/$name" "$bin"
       )
       echo "Installed $name"
     }

     install_gcloud_component gke-gcloud-auth-plugin \
       "https://dl.google.com/dl/cloudsdk/channels/rapid/components/google-cloud-sdk-gke-gcloud-auth-plugin-darwin-arm-20260522195849.tar.gz"

     install_gcloud_component cloud-run-proxy \
       "https://dl.google.com/dl/cloudsdk/channels/rapid/components/google-cloud-sdk-cloud-run-proxy-darwin-arm-20260109121340.tar.gz"
   '';

   time.timeZone = "Asia/Calcutta";
 }

Index: anywhere/hosts/pro-darwin/home.nix
===================================================================
--- anywhere/hosts/pro-darwin/home.nix	
+++ anywhere/hosts/pro-darwin/home.nix	
@@ -1,202 +1,203 @@
 # hosts/pro-darwin/home.nix — home-manager user config for jesbin
 { config, lib, pkgs, ... }:

 {
   home = {
     username = "jesbin";
     homeDirectory = lib.mkForce "/Users/jesbin";
     stateVersion = "24.05";
     sessionPath = [ "/opt/homebrew/bin" "/opt/homebrew/sbin" ];
   };

   programs = {
     zsh = {
       enable = true;
       autosuggestion.enable = true;
       syntaxHighlighting.enable = true;
       envExtra = ''
         export PATH="$HOME/.local/bin:$PATH"
         export PATH="$PATH:/Users/jesbin/Library/Python/3.9/bin"
       '';
       history = {
         size = 50000;
         save = 50000;
         ignoreDups = true;
         share = true;
       };
       shellAliases = {
         gs = "git status";
         gd = "git diff";
         gl = "git log --oneline -20";
         k = "kubectl";
         kx = "kubectx";
       };
       initContent = ''
         # kubectl-aliases (https://github.com/ahmetb/kubectl-aliases)
         [ -f ~/.kubectl_aliases ] && source ~/.kubectl_aliases

         # oh-my-zsh git plugin aliases (https://github.com/ohmyzsh/ohmyzsh/tree/master/plugins/git)
         [ -f ~/.oh-my-zsh/plugins/git/git.plugin.zsh ] && source ~/.oh-my-zsh/plugins/git/git.plugin.zsh


         # gx: permanently switch gcloud project
         gx() {
           local project
           project=$(gcloud projects list --format='value(projectId)' 2>/dev/null | fzf --prompt='gcloud project> ')
           [ -z "$project" ] && return 0
           if gcloud config set project "$project" 2>/dev/null; then
             echo "Switched to project: $project"
           fi
         }

         # tgx: temporarily switch gcloud project for this shell session only
         tgx() {
           local project
           project=$(gcloud projects list --format='value(projectId)' 2>/dev/null | fzf --prompt='gcloud project (temp)> ')
           [ -z "$project" ] && return 0
           export CLOUDSDK_CORE_PROJECT="$project"
           echo "CLOUDSDK_CORE_PROJECT=$project (session only)"
         }
       '';
     };

     git = {
       enable = true;
       settings = {
         user.name = "jesbinjoseph";
         user.email = "jesbin.joseph@egovernments.org";
         init.defaultBranch = "main";
         pull.rebase = true;
         push.autoSetupRemote = true;
         core.pager = "delta";
         interactive.diffFilter = "delta --color-only";
       };
     };

     bat = {
       enable = true;
       config.theme = "TwoDark";
     };

     delta = {
       enable = true;
       options = {
         navigate = true;
         side-by-side = true;
         line-numbers = true;
       };
     };

     starship = {
       enable = true;
       settings = {
         add_newline = true;
         character = {
           success_symbol = "[❯](bold green)";
           error_symbol = "[❯](bold red)";
         };
       };
     };

     fzf = {
       enable = true;
       enableZshIntegration = true;
     };

     direnv = {
       enable = true;
       nix-direnv.enable = true;
       enableZshIntegration = true;
     };

     jq.enable = true;
     htop.enable = true;
   };

   home.packages = with pkgs; [
     fd
     ripgrep
     yq-go
     tree
     gh
     kubectl
     kubectx
     kubernetes-helm
     opencode
     tailscale
     k9s
+    code-cursor
     firefox
     slack
     google-cloud-sdk
     opentofu
     awscli2
     oci-cli
     sops
     iterm2
     spotify
   ];

   # iTerm2 Dynamic Profile — Dracula theme + JetBrains Mono
   home.file.".kubectl_aliases".source = builtins.fetchurl {
     url = "https://raw.githubusercontent.com/ahmetb/kubectl-aliases/master/.kubectl_aliases";
     sha256 = "sha256:REDACTED";
